'use strict';
const $=id=>document.getElementById(id),M=RFPairMath,canvas=$('combined');
let engines=[],results=null,runId=0,busy=false,drawId=0,view={lat:13.2,lon:101,z:5},drag=null,interference=[null,null],notes=['',''];
const bands=[[-45,'#0000ff'],[-55,'#00a9fe'],[-65,'#00fea9'],[-75,'#00fe00'],[-85,'#a9fe00'],[-95,'#fea900'],[-105,'#ff0000']];
const tick=()=>new Promise(r=>setTimeout(r,0));
const merc=(lat,lon,z)=>({x:(lon+180)/360*256*2**z,y:(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*256*2**z});
function coordinate(x,y,w=canvas.clientWidth,h=canvas.clientHeight){const c=merc(view.lat,view.lon,view.z),span=256*2**view.z;return {lon:(c.x+x-w/2)/span*360-180,lat:Math.atan(Math.sinh(Math.PI*(1-2*(c.y+y-h/2)/span)))*180/Math.PI}}
function screen(lat,lon,w,h){const c=merc(view.lat,view.lon,view.z),p=merc(lat,lon,view.z);return {x:p.x-c.x+w/2,y:p.y-c.y+h/2}}
function tiles(w,h){const c=merc(view.lat,view.lon,view.z),span=2**view.z,old=new Map([...$('tiles').children].map(e=>[e.dataset.key,e])),keep=new Set();for(let y=Math.floor((c.y-h/2)/256);y<=Math.floor((c.y+h/2)/256);y++)for(let x=Math.floor((c.x-w/2)/256);x<=Math.floor((c.x+w/2)/256);x++){if(y<0||y>=span)continue;const key=view.z+':'+x+':'+y;keep.add(key);let img=old.get(key);if(!img){img=new Image();img.alt='';img.dataset.key=key;img.src=`https://tile.openstreetmap.org/${view.z}/${(x%span+span)%span}/${y}.png`;$('tiles').append(img)}img.style.left=Math.round(x*256-c.x+w/2)+'px';img.style.top=Math.round(y*256-c.y+h/2)+'px'}for(const [key,img] of old)if(!keep.has(key))img.remove()}
function options(){const bw=[1,2].map(i=>Number($('bw'+i).value)),fdr=[1,2].map(i=>$('fdr'+i).value.trim()===''?null:Number($('fdr'+i).value));if(bw.some(v=>!Number.isFinite(v)||v<=0)||fdr.some(v=>v!==null&&(!Number.isFinite(v)||v<0||v>300)))throw Error('ตรวจ bandwidth > 0 และ FDR ระหว่าง 0–300 dB');return {bw,fdr}}
let interferenceRevision=0;
async function configureInterference(){const revision=++interferenceRevision,rs=results,next=[null,null],messages=['',''];if(!rs)return;const {bw,fdr}=options();for(let i=0;i<2;i++){const j=1-i,c=rs[i].cfg,o=rs[j].cfg;try{if(Math.abs(c.mobileHeight-o.mobileHeight)>1e-6)throw Error('ความสูงลูกข่ายต่างกัน ต้องตั้งให้เท่ากันแล้วคำนวณใหม่');const reject=M.rejection(c.freq,o.freq,bw[i],bw[j],fdr[i]);if(!Number.isFinite(reject))throw Error('ช่องไม่ทับกันและยังไม่มีค่า FDR ณ Δf นี้');let pattern=null;if(c.mobilePattern==='catalog')pattern=await engines[i].receiverAt(o.freq,c);next[i]={reject,pattern};messages[i]='FDR '+reject.toFixed(2)+' dB · '+(fdr[i]===null?'ประมาณจากสเปกตรัมสี่เหลี่ยม':'ค่าที่ผู้ใช้กรอก')}catch(e){messages[i]='ประเมินไม่ได้: '+e.message}}if(revision!==interferenceRevision||results!==rs)return;interference=next;notes=messages;$('interferenceStatus').textContent='Δf = '+(Math.abs(rs[0].cfg.freq-rs[1].cfg.freq)*1000).toFixed(3)+' kHz | 2 → 1: '+notes[0]+' | 1 → 2: '+notes[1]}

function at(lat,lon,i){const s=results[i],o=results[1-i],a=interference[i];const c=M.sample(s,s.values.down,lat,lon);if(!a||!Number.isFinite(c))return null;let incident=M.sample(o,o.field,lat,lon);if(!Number.isFinite(incident))return null;let gain=s.cfg.mobileGain;if(a.pattern){const other=M.relative(o.cfg,lat,lon),serving=M.relative(s.cfg,lat,lon),bearing=(Math.atan2(other.x,other.y)*180/Math.PI+540)%360,az=s.cfg.mobileOrientation==='fixed'?s.cfg.mobileAz:(Math.atan2(serving.x,serving.y)*180/Math.PI+540)%360,e=M.sample(o,o.elevation,lat,lon);if(!Number.isFinite(e))return null;gain=a.pattern.gain-RFAntennas.attenuation(a.pattern,bearing,e,az,s.cfg.mobileAntennaTilt||0)}return M.metrics(c,incident+gain-s.cfg.mobileLoss-a.reject,s.cfg.noise.down)}
function legend(){const sinr=$('display').value.startsWith('sinr');$('direction').disabled=sinr;$('weak').disabled=sinr;const colors=sinr?[[null,'#24bfa0','SINR ≥ เกณฑ์ SNR'],[null,'#e64b9d','SINR < เกณฑ์ SNR'],[null,'#89949e','ประเมินไม่ได้']]:bands.filter(b=>$('weak').checked||b[0]>=-95).map((b,i)=>[b[0],b[1],b[0]+' ≤ RSSI'+(i?' < '+bands[i-1][0]:'')+' dBm']);$('legend').replaceChildren(...colors.map(([,color,label])=>{const s=document.createElement('span'),i=document.createElement('i');i.style.background=color;s.append(i,document.createTextNode(label));return s}))}
async function draw(){const token=++drawId,w=Math.round(canvas.clientWidth),h=Math.round(canvas.clientHeight);if(!w||!h)return;tiles(w,h);canvas.width=w;canvas.height=h;legend();const ctx=canvas.getContext('2d');if(!results)return;const pixels=ctx.createImageData(w,h),mode=$('display').value,dir=$('direction').value,minimum=$('weak').checked?-105:-95,colors=bands.map(b=>[b[0],b[1].match(/[a-f\d]{2}/gi).map(v=>parseInt(v,16))]);const lons=Array.from({length:w},(_,x)=>coordinate(x+.5,0,w,h).lon);
for(let y=0;y<h;y++){if(token!==drawId)return;const lat=coordinate(0,y+.5,w,h).lat;for(let x=0;x<w;x++){const lon=lons[x];let color=null;if(mode.startsWith('sinr')){const i=mode==='sinr1'?0:1,c=M.sample(results[i],results[i].values.down,lat,lon);if(Number.isFinite(c)&&c>=results[i].cfg.threshold){const v=at(lat,lon,i);color=!v?[137,148,158]:v.sinr>=results[i].cfg.requiredSNR?[36,191,160]:[230,75,157]}}else{const a=mode==='two'?NaN:M.sample(results[0],results[0].values[dir],lat,lon),b=mode==='one'?NaN:M.sample(results[1],results[1].values[dir],lat,lon),v=M.merge(a,b);if(Number.isFinite(v)&&v>=minimum)color=colors.find(b=>v>=b[0])?.[1]}if(color){const k=(y*w+x)*4;pixels.data.set(color,k);pixels.data[k+3]=175}}if(y%24===0)await tick()}
if(token!==drawId)return;ctx.putImageData(pixels,0,0);results.forEach((s,i)=>{const p=screen(s.cfg.lat,s.cfg.lon,w,h);ctx.fillStyle='#102637';ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,8,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.font='bold 14px system-ui';ctx.fillText('สถานี '+(i+1),p.x+12,p.y-10)})}
function home(){if(results){const north=Math.max(...results.map(s=>s.cfg.lat+s.cfg.radius/111.195)),south=Math.min(...results.map(s=>s.cfg.lat-s.cfg.radius/111.195)),east=Math.max(...results.map(s=>s.cfg.lon+s.cfg.radius/(111.195*Math.cos(s.cfg.lat*Math.PI/180)))),west=Math.min(...results.map(s=>s.cfg.lon-s.cfg.radius/(111.195*Math.cos(s.cfg.lat*Math.PI/180))));view={lat:(north+south)/2,lon:(east+west)/2,z:3};for(let z=3;z<=16;z++){const a=merc(north,west,z),b=merc(south,east,z);if(b.x-a.x>canvas.clientWidth*.85||b.y-a.y>canvas.clientHeight*.85)break;view.z=z}}draw()}
function point(p){if(!results)return;const f=v=>Number.isFinite(v)?v.toFixed(1):'ไม่มีข้อมูล',lines=[p.lat.toFixed(6)+', '+p.lon.toFixed(6)];for(let i=0;i<2;i++){const s=results[i],v=at(p.lat,p.lon,i);lines.push('สถานี '+(i+1)+': DL '+f(M.sample(s,s.values.down,p.lat,p.lon))+' dBm · UL '+f(M.sample(s,s.values.up,p.lat,p.lon))+' dBm');lines.push(v?'  I '+f(v.i)+' dBm · C/I '+f(v.ci)+' dB · SINR '+f(v.sinr)+' dB (เกณฑ์ '+s.cfg.requiredSNR+' dB)':'  Interference: '+(interference[i]?'ไม่มีข้อมูลครบทั้งสองเส้นทาง ณ จุดนี้':notes[i]))}$('point').textContent=lines.join('\n')}
function lock(on){busy=on;for(const i of [1,2])$('station'+i).inert=on;document.body.classList.toggle('busy',on);$('runPair').disabled=on;$('cancelPair').disabled=!on;for(const id of ['bw1','bw2','fdr1','fdr2'])$(id).disabled=on}
$('runPair').onclick=async()=>{let token;try{options();await Promise.all(engines.map(e=>e.ready));engines.forEach((e,i)=>{try{e.validate()}catch(err){throw Error('สถานี '+(i+1)+': '+err.message)}});token=++runId;lock(true);results=null;interference=[null,null];draw();$('point').textContent='กำลังคำนวณทั้งสองสถานี…';$('status').textContent='กำลังคำนวณ 2 สถานีพร้อมกัน';const start=performance.now();const timer=setInterval(()=>{if(token===runId)engines.forEach((e,i)=>$('s'+(i+1)).textContent=e.status())},500);let out;try{out=await Promise.all(engines.map(async(e,i)=>{try{return await e.run()}catch(err){throw Error('สถานี '+(i+1)+': '+err.message)}}))}finally{clearInterval(timer)}if(token!==runId)return;results=out;await configureInterference();if(token!==runId)return;$('status').textContent='สำเร็จ · เวลารวม '+((performance.now()-start)/1000).toFixed(1)+' วินาที';out.forEach((s,i)=>$('s'+(i+1)).textContent=s.cfg.freq+' MHz · '+s.n+' × '+s.n+' จุด · '+s.cfg.actualGridM.toFixed(1)+' m/ช่อง · รวมโหลด DEM '+s.seconds.toFixed(1)+' วินาที');$('point').textContent='คลิกแผนที่เพื่ออ่านค่าทั้งสองสถานีและ C/I / SINR';home()}catch(e){if(token&&token!==runId)return;engines.forEach(e=>e.cancel());results=null;draw();$('status').textContent=e.message}finally{if(!token||token===runId)lock(false)}};
$('cancelPair').onclick=()=>{++runId;engines.forEach(e=>e.cancel());results=null;draw();lock(false);$('status').textContent='หยุดทั้งสองสถานีแล้ว · ไม่มีผลบางส่วนบนแผนที่รวม'};
for(const id of ['display','direction','weak'])$(id).onchange=()=>{persist();draw()};
window.rfPairEdited=()=>{if(results&&!busy)$('status').textContent='แก้ไขพารามิเตอร์แล้ว · แผนที่รวมยังเป็นผลเดิม กดคำนวณทั้งสองเพื่ออัปเดต'};
let interferenceChange=0;for(const id of ['bw1','bw2','fdr1','fdr2'])$(id).onchange=async()=>{persist();const t=++interferenceChange;try{await configureInterference();if(t===interferenceChange)draw()}catch(e){$('interferenceStatus').textContent=e.message;interference=[null,null];draw()}};
function persist(){try{localStorage.setItem('rf-pair-options',JSON.stringify(Object.fromEntries(['bw1','bw2','fdr1','fdr2','display','direction','weak'].map(id=>[id,id==='weak'?$(id).checked:$(id).value]))))}catch{}}
try{const stored=JSON.parse(localStorage.getItem('rf-pair-options')||'null');if(stored)for(const id of ['bw1','bw2','fdr1','fdr2','display','direction','weak'])if(id in stored){if(id==='weak')$(id).checked=stored[id];else $(id).value=stored[id]}}catch{}
function zoom(d){view.z=Math.max(3,Math.min(16,view.z+d));draw()}
$('plus').onclick=()=>zoom(1);$('minus').onclick=()=>zoom(-1);$('home').onclick=home;
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,start:merc(view.lat,view.lon,view.z),moved:false}};
canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)drag.moved=true;if(!drag.moved)return;const span=256*2**view.z;view.lon=(drag.start.x-dx)/span*360-180;view.lat=Math.max(-85,Math.min(85,Math.atan(Math.sinh(Math.PI*(1-2*(drag.start.y-dy)/span)))*180/Math.PI));draw()};
canvas.onpointerup=e=>{if(drag&&!drag.moved){const r=canvas.getBoundingClientRect();point(coordinate(e.clientX-r.left,e.clientY-r.top))}drag=null};canvas.onpointercancel=()=>drag=null;
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1:-1)},{passive:false});new ResizeObserver(draw).observe(canvas);
Promise.all([1,2].map(i=>new Promise((resolve,reject)=>{const frame=$('station'+i);const finish=()=>{const api=frame.contentWindow.RFPair;if(api)resolve(api);else reject(Error('โหลดตัวคำนวณสถานี '+i+' ไม่สำเร็จ กรุณารีเฟรช'))};if(frame.contentDocument?.readyState==='complete'&&frame.contentWindow.RFPair)finish();else frame.addEventListener('load',finish,{once:true})}))).then(async list=>{engines=list;await Promise.all(list.map(e=>e.ready));$('runPair').disabled=false;$('status').textContent='พร้อม · กรอกพารามิเตอร์แยกทั้งสองสถานี';draw()}).catch(e=>$('status').textContent=e.message);
